def evaluate(current_reputation: float, observation: dict, my_history: list[dict], round_num: int) -> float:
    recipient_rep = observation['recipient_reputation']
    action = observation['action']

    # Adaptive delta based on action and recipient reputation
    if action == 'donate':
        delta = 0.3 * (1 + recipient_rep)
    else:
        delta = -0.4 * (1 - recipient_rep)

    # History-based learning rate: decrease influence as we gain more experience
    experience = max(0, min(1, len(my_history) / 30))  # saturates after ~30 rounds
    learning_rate = 0.15 + 0.1 * (1 - experience)

    # Incorporate a momentum term from recent history (last 5 observations)
    if len(my_history) >= 5:
        recent_deltas = []
        for h in my_history[-5:]:
            if h.get('action') == 'donate':
                recent_deltas.append(0.3 * (1 + h.get('recipient_reputation', 0)))
            else:
                recent_deltas.append(-0.4 * (1 - h.get('recipient_reputation', 0)))
        avg_recent_delta = sum(recent_deltas) / len(recent_deltas)
        delta = 0.7 * delta + 0.3 * avg_recent_delta  # blend with current delta

    new_reputation = current_reputation + learning_rate * delta
    return max(-1.0, min(1.0, new_reputation))


def decide(recipient_reputation: float, round_num: int, my_history: list[dict]) -> bool:
    # Compute median of recipient reputations seen so far (more robust than mean)
    if my_history:
        reps = sorted([h['recipient_reputation'] for h in my_history])
        mid = len(reps) // 2
        if len(reps) % 2 == 0:
            median_rep = (reps[mid-1] + reps[mid]) / 2.0
        else:
            median_rep = reps[mid]
    else:
        median_rep = 0.0

    # Threshold increases with round number but is also adjusted by median reputation
    # More generous early, then gradually stricter
    base = 0.05 * (round_num ** 0.8) / (30 ** 0.8)  # sublinear growth, reaching ~0.05 by round 30
    threshold = base + 0.15 * median_rep
    threshold = max(-0.3, min(0.3, threshold))

    # Add a small random exploration (5% chance to donate even if below threshold)
    import random
    if recipient_reputation > threshold:
        return True
    else:
        return random.random() < 0.05

def evaluate(current_reputation: float, observation: dict, my_history: list[dict], round_num: int) -> float:
    # Use a simple "stern judging" norm: reward cooperative acts towards good reputations
    # and uncooperative acts towards bad reputations.
    recipient_rep = observation['recipient_reputation']
    action = observation['action']

    if action == 'donate':
        if recipient_rep > 0.2:
            delta = 0.4   # good to give to good
        else:
            delta = -0.4  # bad to give to neutral/bad
    else:  # not donate
        if recipient_rep < -0.2:
            delta = 0.4   # good to refuse to bad
        else:
            delta = -0.4  # bad to refuse to neutral/good

    # Fixed learning rate, with moderate momentum toward current reputation
    alpha = 0.3
    new_reputation = (1 - alpha) * current_reputation + alpha * delta
    return max(-1.0, min(1.0, new_reputation))


