        delta = 0.2 * (1 + recipient_rep) / (1 + abs(recipient_rep))
    else:
        delta = -0.3 * (1 - recipient_rep) / (1 + abs(recipient_rep))
    # Recent momentum from last 8 actions
    if len(my_history) >= 8:
        rec = 0.0
        for h in my_history[-8:]:
            if h.get('action') == 'donate':
                rec += 0.2 * (1 + h.get('recipient_reputation', 0)) / (1 + abs(h.get('recipient_reputation', 0)))
            else:
                rec += -0.3 * (1 - h.get('recipient_reputation', 0)) / (1 + abs(h.get('recipient_reputation', 0)))
        rec /= 8
        delta = 0.5 * delta + 0.5 * rec
    # Learning rate decreases with round number
    lr = 0.15 + 0.1 * (1 - min(1.0, round_num / 40.0))
    new_rep = current_reputation + lr * delta
    return max(-1.0, min(1.0, new_rep))


